package org.apache.sshd.sftp.client; import java.io.*; import java.util.*; public interface SftpClient extends Closeable { enum OpenMode {Append,Write,Create,Truncate} enum CopyMode {Atomic,Overwrite} OutputStream write(String p, OpenMode... m) throws IOException; InputStream read(String p) throws IOException; Attributes stat(String p) throws IOException; void rename(String s,String t,CopyMode... m) throws IOException; void remove(String p) throws IOException; Iterable<DirEntry> readDir(String p) throws IOException; class Attributes { public long getSize(){return 0;} } class DirEntry { public String getFilename(){return "x";} } }
